    @Override protected void onDestroy(){io.shutdown();super.onDestroy();}
    @Override public void onBackPressed(){if(step>0)go(step-1);else super.onBackPressed();}
    @Override public boolean dispatchTouchEvent(MotionEvent e){if(e.getActionMasked()==MotionEvent.ACTION_DOWN){downX=e.getX();downY=e.getY();}if(e.getActionMasked()==MotionEvent.ACTION_UP){float dx=e.getX()-downX,dy=e.getY()-downY;int[] p=new int[2];scroll.getLocationOnScreen(p);if(Math.abs(dx)>u.d(75)&&Math.abs(dx)>Math.abs(dy)*1.6&&downY>p[1]&&downY<p[1]+scroll.getHeight()){int n=step+(dx<0?1:-1);if(n>=0&&n<9){MotionEvent c=MotionEvent.obtain(e);c.setAction(MotionEvent.ACTION_CANCEL);super.dispatchTouchEvent(c);c.recycle();go(n);return true;}}}return super.dispatchTouchEvent(e);}
    private void go(int n){if(n<0||n>=9||n==step)return;int direction=n>step?1:-1;step=n;prefs.edit().putInt("page",step).apply();render(true,direction);}
