    private void chinaPage(){u.heading(page,"Китайская лента","Убираем новости и рекомендации слева от рабочего стола.");boolean manual=prefs.getBoolean("news_checked",false);u.status(page,nativeOn()?"Страница заменена Google":manual?"Отмечено тобой":"Нужна настройка",nativeOn()?"К штатному рабочему столу подключён Discover. Китайская страница не показывается.":"У ленты ColorOS нет доступного общего переключателя для сторонних приложений. Здесь — ручной шаг; далее можно подключить Discover.",nativeOn()?2:manual?1:0);u.note(page,"Выключи два пункта","На левой странице ColorOS открой профиль → настройки → настройку содержимого. Выключи Trending news / ленту новостей и Recommended services / рекомендуемые сервисы. Названия зависят от языка прошивки.");action("Вернуться на рабочий стол",true,this::home);action(manual?"Отметка сохранена ✓":"Я выключил новости и рекомендации",false,()->mark("news_checked"));action("Перейти к Google Discover  →",false,()->go(2));u.note(page,"Ручная проверка","Эта отметка означает твоё подтверждение. Приложение не читает закрытые настройки китайской ленты.");}
