    private void appRow(FixData.GoogleApp app,Runnable tap){LinearLayout row=u.row();row.setPadding(u.d(16),u.d(14),u.d(14),u.d(14));row.setBackground(u.round(u.surface,22));row.addView(u.appIcon(app.pkg()),new LinearLayout.LayoutParams(u.d(39),u.d(39)));LinearLayout labels=u.column();labels.setPadding(u.d(13),0,u.d(10),0);labels.addView(u.text(app.name(),15,u.ink,true));labels.addView(u.text(app.purpose(),12,u.muted,false));row.addView(labels,new LinearLayout.LayoutParams(0,-2,1));row.addView(u.text(FixData.installed(this,app.pkg())?"✓  ›":"＋",19,FixData.installed(this,app.pkg())?u.green:u.blue,true));row.setOnClickListener(v->tap.run());row.setClickable(true);u.add(page,row,9);}
    private void appDialog(FixData.GoogleApp a){if(!FixData.installed(this,a.pkg())){market(a.pkg());return;}ArrayList<String> labels=new ArrayList<>(List.of("Открыть","Разрешения приложения","Системные настройки"));ArrayList<Runnable> actions=new ArrayList<>(List.of(()->openApp(a.pkg()),()->permissionDialog(a),()->details(a.pkg())));String role=switch(a.pkg()){case "com.google.android.dialer"->"DIALER";case "com.google.android.apps.messaging"->"SMS";case "com.android.chrome"->"BROWSER";case "com.google.android.googlequicksearchbox"->"ASSISTANT";default->null;};if(role!=null){labels.add("Сделать стандартным");actions.add(()->apply(a.name(),"Назначить «"+a.name()+"» стандартным приложением для этой функции? Android проверит, подходит ли приложение для роли.",role.equals("ASSISTANT")?FixData.assistant():FixData.role(role,a.pkg())));}if(a.pkg().equals("com.google.android.inputmethod.latin")){labels.add("Использовать Gboard");actions.add(()->apply("Клавиатура Gboard","Включить Gboard и сделать её текущей клавиатурой?",FixData.gboard()));}
        String category=switch(a.pkg()){case "com.google.android.contacts"->"android.intent.category.APP_CONTACTS";case "com.google.android.calendar"->"android.intent.category.APP_CALENDAR";case "com.google.android.calculator"->"android.intent.category.APP_CALCULATOR";case "com.google.android.gm"->"android.intent.category.APP_EMAIL";default->null;};if(category!=null){labels.add("Выбрать в системном меню");actions.add(()->new AlertDialog.Builder(this).setTitle("Выбор по умолчанию").setMessage("Если Android предложит выбор, укажи «"+a.name()+"» и «Всегда». Если выбор уже сохранён, сразу откроется текущее приложение.").setPositiveButton("Открыть",(d,w)->safeStart(new Intent(Intent.ACTION_MAIN).addCategory(category))).setNegativeButton("Отмена",null).show());}if(a.pkg().equals("com.google.android.deskclock")){labels.add("Выбрать часы по умолчанию");actions.add(()->safeStart(new Intent("android.intent.action.SHOW_ALARMS")));}if(a.pkg().equals("com.google.android.keep")){labels.add("Выбрать для новых заметок");actions.add(()->safeStart(new Intent("com.google.android.gms.actions.CREATE_NOTE")));}if(a.pkg().equals("com.google.android.calculator")){boolean disabled="1".equals(fact("calculator_off"));labels.add(disabled?"Вернуть калькулятор ColorOS":"Скрыть калькулятор ColorOS");actions.add(()->apply("Калькулятор ColorOS",disabled?"Вернуть штатный калькулятор в исходное состояние?":"Отключить только штатный калькулятор для текущего пользователя? Его данные сохранятся. Калькулятор Google уже установлен.",FixData.calculator(!disabled)));}new AlertDialog.Builder(this).setTitle(a.name()).setItems(labels.toArray(new String[0]),(d,i)->actions.get(i).run()).setNegativeButton("Закрыть",null).show();}
    private void permissionDialog(FixData.GoogleApp a){var list=FixData.permissions(this,a.pkg());if(list.isEmpty()){new AlertDialog.Builder(this).setTitle(a.name()).setMessage("Обычные запрашиваемые разрешения не найдены. Дополнительные доступы открываются в системных настройках.").setPositiveButton("Понятно",null).show();return;}String[] labels=new String[list.size()];boolean[] chosen=new boolean[list.size()];for(int i=0;i<list.size();i++){var p=list.get(i);labels[i]=p.label()+"\n"+p.name()+(p.granted()?"  · уже разрешено":"");}new AlertDialog.Builder(this).setTitle("Доступы: "+a.name()).setMultiChoiceItems(labels,chosen,(d,i,b)->chosen[i]=b).setNeutralButton("Все доступы…",(d,w)->apply(a.name(),permissionText(a,list),FixData.grant(this,a.pkg(),list))).setPositiveButton("Разрешить выбранные",(d,w)->{ArrayList<FixData.Permission> selected=new ArrayList<>();for(int i=0;i<chosen.length;i++)if(chosen[i])selected.add(list.get(i));if(selected.isEmpty()){toast("Ничего не выбрано");return;}apply(a.name(),permissionText(a,selected),FixData.grant(this,a.pkg(),selected));}).setNegativeButton("Отмена",null).show();}
    private String permissionText(FixData.GoogleApp a,List<FixData.Permission> list){StringBuilder b=new StringBuilder("Получатель: ").append(a.name()).append("\n").append(a.pkg()).append("\n\nРазрешить следующие запрошенные самим приложением доступы?\n\n");for(var p:list)b.append("• ").append(p.label()).append("\n").append(p.name()).append("\n\n");return b.toString();}
    private void prepareEngine(){if(!FixData.installed(this,FixData.ENGINE)){installEngine();return;}if(!FixData.trustedEngine(this)){new AlertDialog.Builder(this).setTitle("Версия ColorGoogle не подтверждена").setMessage("Подготовка рассчитана на официальный ColorGoogle 16.3.0. Подпись или версия установленного приложения отличается; запуск с правами отладки заблокирован.").setPositiveButton("Понятно",null).show();return;}try{String activation=new String(getAssets().open("activate-colorgoogle.sh").readAllBytes(),StandardCharsets.UTF_8);apply("Подготовка ColorGoogle","ColorGoogle получит чтение системных журналов (READ_LOGS), уведомления и показ поверх приложений. Это нужно для поиска и системных жестов. Работающий агент сохранится; отсутствующий будет запущен. Настройки самого ColorGoogle выбираются в нём отдельно.",FixData.prepareEngine(activation));}catch(Exception e){toast("Не найден встроенный сценарий");}}
    private void installEngine(){if(!getPackageManager().canRequestPackageInstalls()){confirm("Установка ColorGoogle","Разреши re:GoogleMaid устанавливать приложения из этого источника. Затем вернись и нажми установку ещё раз. Встроен официальный ColorGoogle 16.3.0; перед установкой проверяется SHA-256 файла.",()->safeStart(new Intent(Settings.ACTION_MANAGE_UNKNOWN_APP_SOURCES,Uri.parse("package:"+getPackageName()))));return;}if(busy)return;busy=true;banner("Проверка встроенного ColorGoogle…");io.execute(()->{try{File f=new File(getCacheDir(),"ColorGoogle-16.3.0.apk");MessageDigest hash=MessageDigest.getInstance("SHA-256");try(InputStream in=getAssets().open("ColorGoogle-16.3.0.apk");OutputStream out=new FileOutputStream(f)){byte[] buf=new byte[32768];int n;while((n=in.read(buf))>0){out.write(buf,0,n);hash.update(buf,0,n);}}if(!HexFormat.of().formatHex(hash.digest()).equals("7b8c34a5bcfc6c7c5db3d5d1f1ab4fd37d07e27215762e2f4a204b598887bc84"))throw new IOException("Не совпал SHA-256 файла");main.post(()->{busy=false;if(isFinishing()||isDestroyed())return;banner("ColorGoogle проверен. Подтверди установку Android.");safeStart(new Intent(Intent.ACTION_VIEW).setDataAndType(Uri.parse("content://dev.local.ace6tdiscover.dependencies/colorgoogle.apk"),"application/vnd.android.package-archive").addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION));});}catch(Exception e){main.post(()->{busy=false;error(e);});}});}
    private void scan(){if(!requireConnection()||busy)return;busy=true;banner("Проверяем текущие настройки…");io.execute(()->{try{String result=new LocalShell(this).run(FixData.check());JSONObject nf=new JSONObject();for(String line:result.split("\n")){int eq=line.indexOf('=');if(eq>0&&line.substring(0,eq).matches("[a-z_]+"))nf.put(line.substring(0,eq),line.substring(eq+1).trim());}main.post(()->{busy=false;facts=nf;prefs.edit().putString("facts",facts.toString()).putLong("checked",System.currentTimeMillis()).apply();banner("Настройки проверены · "+checked());render(false,1);});}catch(Exception e){main.post(()->{busy=false;banner("Проверка не завершена. Открой шаг подключения.");error(e);});}});}
    private void apply(String title,String explanation,String script){confirm(title,explanation,()->{if(!requireConnection()||busy)return;busy=true;banner("Применяем: "+title+"…");io.execute(()->{try{String result=new LocalShell(this).run(script);record(title,true,result);main.post(()->{busy=false;if(isFinishing()||isDestroyed())return;banner("Команды выполнены: "+title);new AlertDialog.Builder(this).setTitle("Шаг выполнен").setMessage("Команды завершились без ошибок. Проверь действие на телефоне; текущее состояние обновится проверкой.").setPositiveButton("Проверить",(d,w)->scan()).setNegativeButton("Закрыть",null).show();});}catch(Exception e){record(title,false,e.getClass().getSimpleName());main.post(()->{busy=false;banner("Шаг не завершён: "+title);error(e);});}});});}
    private void record(String title,boolean ok,String result){String old=prefs.getString("journal","");String entry=new SimpleDateFormat("dd.MM HH:mm",Locale.getDefault()).format(new Date())+" · "+title+" · "+(ok?"команды выполнены":"ошибка")+"\n";prefs.edit().putString("journal",(entry+old).substring(0,Math.min(6000,entry.length()+old.length()))).apply();}
    private void confirm(String title,String message,Runnable yes){new AlertDialog.Builder(this).setTitle(title).setMessage(message).setPositiveButton("Применить",(d,w)->yes.run()).setNegativeButton("Отмена",null).show();}
    private boolean requireConnection(){if(!state.getBoolean("paired",false)||!wireless()){toast("Сначала подключи телефон на шаге 1");if(step!=0)go(0);return false;}return true;}
    private void banner(String text){if(isDestroyed())return;banner.setText(text);banner.setVisibility(View.VISIBLE);}
    private void error(Exception e){if(isFinishing()||isDestroyed())return;Throwable reason=e instanceof ExecutionException&&e.getCause()!=null?e.getCause():e;String message=reason.getMessage();new AlertDialog.Builder(this).setTitle("Не получилось применить").setMessage(message==null?reason.getClass().getSimpleName():message).setPositiveButton("Понятно",null).show();}
    private void mark(String key){prefs.edit().putBoolean(key,true).apply();render(false,1);toast("Проверка сохранена");}
    private void notifications(){if(checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{Manifest.permission.POST_NOTIFICATIONS},20);}
    private void command(String action){startForegroundService(new Intent(this,DiscoverService.class).setAction(action));}
    private void wirelessSettings(){safeStart(new Intent("android.settings.WIRELESS_DEBUGGING_SETTINGS"),new Intent(Settings.ACTION_APPLICATION_DEVELOPMENT_SETTINGS).putExtra(":settings:fragment_args_key","toggle_adb_wireless"));}
    private void home(){safeStart(new Intent(Intent.ACTION_MAIN).addCategory(Intent.CATEGORY_HOME));}
    private void openApp(String pkg){Intent i=getPackageManager().getLaunchIntentForPackage(pkg);if(i==null){if(pkg.equals(FixData.ENGINE))installEngine();else market(pkg);}else safeStart(i);}
    private void details(String p){safeStart(new Intent(Settings.ACTION_APPLICATION_DETAILS_SETTINGS,Uri.parse("package:"+p)));}
    private void market(String p){safeStart(new Intent(Intent.ACTION_VIEW,Uri.parse("market://details?id="+p)),new Intent(Intent.ACTION_VIEW,Uri.parse("https://play.google.com/store/apps/details?id="+p)));}
    private void safeStart(Intent i){safeStart(i,null);}private void safeStart(Intent i,Intent fallback){try{startActivity(i);}catch(Exception e){if(fallback!=null)try{startActivity(fallback);return;}catch(Exception ignored){}toast("Этот экран недоступен на данной прошивке");}}
    private void toast(String t){Toast.makeText(this,t,Toast.LENGTH_LONG).show();}
    private void summary(){int n=0;for(var a:FixData.APPS)if(FixData.installed(this,a.pkg()))n++;String message="Приложения Google: "+n+" / "+FixData.APPS.length+"\nВстроенный Discover: "+(nativeOn()?"подключён при последней проверке":"не подтверждён")+"\nПоиск Google: "+(agentOn()?"перехват включён":"не подтверждён")+"\nНижний жест: "+(prefs.getBoolean("gesture_checked",false)?"проверен тобой":"нужна проверка")+"\nУдержание питания: "+(prefs.getBoolean("power_checked",false)?"проверено тобой":"нужна проверка")+"\n\n"+checked()+"\n\nКамера, галерея и необходимые системные службы ColorOS сохранены. Облачная синхронизация не настраивалась.";new AlertDialog.Builder(this).setTitle("Твоя настройка Google").setMessage(message).setPositiveButton("Проверить заново",(d,w)->scan()).setNegativeButton("Закрыть",null).show();}
    private void about(){String[] items={"О приложении","Журнал действий","Открыть ColorGoogle на GitHub","Лицензии"};new AlertDialog.Builder(this).setTitle("re:GoogleMaid 1.0").setItems(items,(d,n)->{switch(n){case 0->new AlertDialog.Builder(this).setTitle("re:GoogleMaid").setMessage("Пошаговая настройка ColorOS 16 с Google. На базе утилиты Ace6T Discover; локальное сопряжение сохраняется. Метод Discover проверен только на PLR110 / лаунчере 16.6.17.\n\nИсходники и инструкции сборки прилагаются к APK. Это независимый проект, не приложение OPPO или Google.").setPositiveButton("Понятно",null).show();case 1->new AlertDialog.Builder(this).setTitle("Журнал").setMessage(prefs.getString("journal","Действий пока не было")).setPositiveButton("Закрыть",null).show();case 2->safeStart(new Intent(Intent.ACTION_VIEW,Uri.parse("https://github.com/joeyandu/ColorGoogle")));case 3->license();}}).setNegativeButton("Закрыть",null).show();}
    private void license(){try{String value=new String(getAssets().open("LICENSE.txt").readAllBytes(),StandardCharsets.UTF_8);ScrollView s=new ScrollView(this);TextView t=u.text("GPL-3.0-only\n\nColorGoogle и adbclient: joeyandu/ColorGoogle; MiCTS: parallelcc/MiCTS.\n\n"+value,12,u.ink,false);t.setPadding(u.d(20),u.d(12),u.d(20),u.d(12));s.addView(t);new AlertDialog.Builder(this).setTitle("Открытый исходный код").setView(s).setPositiveButton("Закрыть",null).show();}catch(Exception e){toast("Лицензия GPL-3.0-only включена в исходники");}}
